  const on = en.flashT > 0 || en.attackFlash > 0;
  for (const o of en.flashables) o.material.color.setHex(on ? 0xffffff : o.material.userData.baseColor);
}

function animateWalk(en, dt, a) {
  const p = en.parts;
  en.walkT += dt * a.walkFreq;
  const w = en.walkT;
  const s = Math.sin(w);
  const s2 = Math.sin(w + a.asym);
  p.legL.rotation.z = s * a.leg;
  p.legR.rotation.z = s2 * a.leg;
  p.armL.rotation.z = a.armRest + Math.sin(w + a.asym) * a.arm * 0.9;
  p.armR.rotation.z = a.armRest + Math.sin(w) * a.arm * 0.9;
  p.torso.rotation.z = en.lean - a.lean + Math.sin(w * 2) * 0.05;
  p.body.position.x = Math.sin(w * 2) * 0.02;
  p.body.position.y = a.crouch;
  p.head.rotation.y = Math.sin(w * 0.7) * 0.1;
  p.head.rotation.x = a.headLoll * 0.3 + Math.sin(w * 0.5) * 0.05;
  en.bob = Math.abs(s) * a.bob;
}

function animateIdle(en, dt, a) {
  const t = en.animT, p = en.parts;
  const settle = Math.min(1, dt * 8);
  p.legL.rotation.z += (0 - p.legL.rotation.z) * settle;
  p.legR.rotation.z += (0 - p.legR.rotation.z) * settle;
  p.armL.rotation.z += (a.armRest - p.armL.rotation.z) * settle;
  p.armR.rotation.z += (a.armRest - p.armR.rotation.z) * settle;
  const br = Math.sin(t * 2.2) * a.breath;
  p.body.scale.y = 1 + br;
  p.body.scale.x = 1 - br * 0.5;
  p.body.scale.z = 1 - br * 0.5;
  p.body.position.y = a.crouch + Math.sin(t * 2.2) * 0.012;
  p.torso.rotation.z += (en.lean + Math.sin(t * 1.6) * 0.03 - p.torso.rotation.z) * Math.min(1, dt * 5);
  const tw = Math.pow(Math.max(0, Math.sin(t * 0.8)), 30);
  p.head.rotation.y = Math.sin(t * 0.6) * 0.4 + tw * 0.6;
  p.head.rotation.x = Math.sin(t * 0.9) * 0.06 + tw * 0.2;
  p.armL.rotation.z += tw * 0.4;
  p.armR.rotation.z += tw * 0.4;
  en.bob = Math.sin(t * 2.2) * 0.015;
}

// Ataque: windup (braços p/ trás) → strike → recuperação. O dano continua
// disparando no início do ataque (update() inalterado) — a animação lê o
// mesmo attackT/attackDur e a pose final volta ao repouso p/ transição suave.
function animateAttack(en, a) {
  const AP = 1 - en.attackT / en.attackDur;
  const p = en.parts;
  const type = en.type;
  p.legL.rotation.z = 0;
  p.legR.rotation.z = 0;
  let arm, bx, tz, hx, bodyY;
  if (type === 'demon') {
    const lunge = Math.sin(Math.min(1, AP / 0.35) * Math.PI);
    const rec = Math.min(1, Math.max(0, (AP - 0.35) / 0.65));
    arm = -0.5 + lunge * 2.2;
    bx = -0.12 + lunge * 0.55;
    tz = en.lean + 0.12 - lunge * 0.28;
    hx = -0.3 + lunge * 0.4;
    bodyY = a.crouch - lunge * 0.05 * (1 - rec);
    p.armL.rotation.z = arm + (a.armRest - arm) * rec;
    p.armR.rotation.z = arm + (a.armRest - arm) * rec;
    p.body.position.x = bx + (0 - bx) * rec;
    p.torso.rotation.z = tz + (en.lean - tz) * rec;
    p.head.rotation.x = hx + (0 - hx) * rec;
  } else if (type === 'zombie') {
    const sw = Math.sin(Math.min(1, AP / 0.5) * Math.PI);
    const rec = Math.min(1, Math.max(0, (AP - 0.5) / 0.5));
    arm = -1.2 + sw * 2.7;
    bx = -0.06 + sw * 0.32;
    tz = en.lean + 0.1 - sw * 0.22;
    hx = -0.2 + sw * 0.35;
    p.armL.rotation.z = arm + (a.armRest - arm) * rec;
    p.armR.rotation.z = arm + (a.armRest - arm) * rec;
    p.body.position.x = bx + (0 - bx) * rec;
    p.torso.rotation.z = tz + (en.lean - tz) * rec;
    p.head.rotation.x = hx + (0 - hx) * rec;
    bodyY = a.crouch;
  } else {
    const th = Math.sin(Math.min(1, AP / 0.35) * Math.PI);
    const rec = Math.min(1, Math.max(0, (AP - 0.35) / 0.65));
    arm = -1.5 + th * 3.3;
    bx = -0.1 + th * 0.32;
    tz = en.lean + 0.18 - th * 0.32;
    hx = -0.15 + th * 0.25;
    p.armL.rotation.z = arm + (a.armRest - arm) * rec;
    p.armR.rotation.z = arm + (a.armRest - arm) * rec;
    p.body.position.x = bx + (0 - bx) * rec;
    p.torso.rotation.z = tz + (en.lean - tz) * rec;
    p.head.rotation.x = hx + (0 - hx) * rec;
    bodyY = a.crouch;
  }
  p.body.position.y = bodyY;
  p.head.rotation.y = 0;
  en.bob = Math.sin(en.animT * 14) * 0.01;
}

// Antecipação: tensão pré-ataque — agacha e recua os braços/cabeça conforme o
// cooldown se aproxima de zero (visual apenas; não altera a IA).
function applyAnticipation(en, a, ant) {
  if (ant <= 0) return;
  const p = en.parts;
  const type = en.type;
  let armBack, bodyBack, torsoBack, headBack, crouch;
  if (type === 'demon') {
    armBack = -0.5; bodyBack = -0.15; torsoBack = 0.14; headBack = -0.3; crouch = -0.05;
  } else if (type === 'zombie') {
    armBack = -1.0; bodyBack = -0.05; torsoBack = 0.08; headBack = -0.15; crouch = -0.02;
  } else {
    armBack = -1.4; bodyBack = -0.08; torsoBack = 0.18; headBack = -0.2; crouch = -0.03;
  }
  p.armL.rotation.z += (armBack - p.armL.rotation.z) * ant;
  p.armR.rotation.z += (armBack - p.armR.rotation.z) * ant;
  p.body.position.x += (bodyBack - p.body.position.x) * ant;
  p.torso.rotation.z += (en.lean + torsoBack - p.torso.rotation.z) * ant;
  p.head.rotation.x += (headBack - p.head.rotation.x) * ant;
  p.body.position.y += (crouch - p.body.position.y) * ant;
}

function animate(en, dt, moving) {
  const parts = en.parts;
  const a = ANIM[en.type];
  if (en.attackT > 0) animateAttack(en, a);
  else if (moving) animateWalk(en, dt, a);
  else animateIdle(en, dt, a);
  applyAnticipation(en, a, en.ant || 0);
  const f = en.flinch > 0 ? en.flinch / 0.12 : 0;
  if (f > 0) {
    parts.body.scale.set(1 + f * 0.2, 1 - f * 0.25, 1 + f * 0.2);
    parts.body.position.x -= f * 0.18;
    parts.head.rotation.x -= f * 0.35;
  }
}

function animateDeath(en, dt) {
  en.deathT += dt;
  const T = en.deathT;
  if (T < 0.01) {
    for (const o of en.flashables) o.material.transparent = true;
  }
  if (T < 0.1) {
    for (const o of en.flashables) o.material.color.setHex(0xffffff);
  } else {
    for (const o of en.flashables) o.material.color.setHex(o.material.userData.baseColor);
  }
  const pop = T < 0.12 ? 1 + 0.3 * (1 - T / 0.12) : 1;
  en.mesh.scale.set(pop, pop, pop);
  const fall = Math.min(1, T / DEATH_FALL);
  const ease = 1 - Math.pow(1 - fall, 3);
  const dir = en.deathDir;
  const recoil = Math.sin(Math.min(1, T / 0.07) * Math.PI) * 0.2 * -dir;
  en.mesh.rotation.z = recoil + dir * Math.PI / 2 * ease;
  en.mesh.rotation.x = Math.sin(T * 4) * 0.12 * ease;
  en.mesh.position.y = en.y - fall * 0.15;
  if (T > DEATH_FALL) {
    const sink = Math.min(1, (T - DEATH_FALL) / DEATH_SINK);
    en.mesh.position.y = en.y - 0.15 - sink * 0.5;
    const alpha = 1 - sink;
    for (const o of en.flashables) o.material.opacity = Math.max(0, alpha);
  }
  if (T >= DEATH_FALL + DEATH_SINK) en.mesh.visible = false;
}

